Write a Vitest test for this Vue 3 <script setup> component, which saves on button click after an async validation call:

```vue
<script setup lang="ts">
import { ref } from 'vue';
import { validateName } from '../api/nameClient';
const props = defineProps<{ title: string }>();
const emit = defineEmits<{ save: [string] }>();
const name = ref('');
async function onSave() {
  const ok = await validateName(name.value);
  if (ok) emit('save', name.value);
}
</script>
<template>
  <h1>{{ title }}</h1>
  <input v-model="name" />
  <button @click="onSave">Save</button>
</template>
```

Write tests for this composable, which relies on an injected key:

```typescript
import { inject } from 'vue';
import type { InjectionKey } from 'vue';
export const ApiKey: InjectionKey<{ getCount: () => number }> = Symbol('api');

export function useCount() {
  const api = inject(ApiKey);
  if (!api) throw new Error('ApiKey not provided');
  return { count: api.getCount() };
}
